#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class MercenaryCapture:MonoBehaviour
{
 string folder;int passed;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-mercenary-capture"))return;var go=new GameObject("Mercenary checks");DontDestroyOnLoad(go);go.AddComponent<MercenaryCapture>();}
 void Check(bool ok,string note){if(!ok)throw new Exception(note);passed++;}
 IEnumerator Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/Mercenaries"));Directory.CreateDirectory(folder);SaveGames.TestRoot=Path.Combine(folder,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.json");var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+passed+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(folder,"checks.txt"),passed+" mercenary checks passed");Application.Quit(0);}
 IEnumerator Run(){Application.runInBackground=true;yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);CampaignHUD.Instance.DismissReport();VariableSingleton.SetInt("iMoney",1000000);CountryDiplomacy.ChangeGoodwill(CountryDiplomacy.Index("hospitallers"),60);var baseline=VariableSingleton.Instance.CaptureState();
 foreach(var own in new[]{0,10,15,16,100})foreach(var enemy in new[]{0,10,15,16,100}){VariableSingleton.SetInt("iShips",own);VariableSingleton.SetInt("iTurkShips",enemy);Check(NavalState.Dominance==(own*2>enemy*3?NavalState.Control.Imperial:enemy*2>own*3?NavalState.Control.Ottoman:NavalState.Control.Contested),"strict dominance");}
 VariableSingleton.SetInt("iShips",100);VariableSingleton.SetInt("iTurkShips",10);VariableSingleton.ChangeBool("bStraitsOpen",true);
 Check(MercenaryContracts.SafeChance(4)==75,"Tatar imperial75");VariableSingleton.SetInt("iShips",10);Check(MercenaryContracts.SafeChance(4)==69,"Tatar contested69");VariableSingleton.SetInt("iTurkShips",100);Check(MercenaryContracts.SafeChance(4)==63,"Tatar Ottoman63");VariableSingleton.ChangeBool("bStraitsOpen",false);Check(MercenaryContracts.SafeChance(4)==13,"Tatar closed13");
 for(int id=0;id<20;id++){VariableSingleton.Instance.RestoreValidated(baseline);var c=MercenaryRoster.All[id];int gold=DailyLifeEvents.I("iMoney"),foot=DailyLifeEvents.I("iInfantry"),population=(int)PopulationAccounting.People;Check(c.Days<=75,"baseline75");Check(MercenaryContracts.Sign(id,out _,false),"sign "+id);Check(DailyLifeEvents.I("iMoney")==gold-c.Gold/2,"half upfront");Check(!MercenaryContracts.Sign(id,out _,false),"no duplicate signing");int incident=MercenaryContracts.Get(id,"Incident"),due=MercenaryContracts.Get(id,"Due");SaveGames.Checkpoint();var archive=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(archive.campaign);Check(MercenaryContracts.Get(id,"Incident")==incident&&MercenaryContracts.Get(id,"Due")==due,"saved voyage");MercenaryContracts.Put(id,"Incident",0);MercenaryContracts.Advance(VariableSingleton.GetDate().AddDays(c.Days));Check(MercenaryContracts.State(id)==MercenaryContracts.Status.Payment,"arrival payment");MercenaryContracts.Resolve(id,0);Check(DailyLifeEvents.I("iInfantry")==foot+c.Infantry,"exact troops");Check(PopulationAccounting.People==population+c.Land+c.Ships*50+c.Cannons*5+c.Engineers+(c.Sanctuary?150:0),"population includes crew once");int paid=DailyLifeEvents.I("iMoney");MercenaryContracts.Resolve(id,0);Check(DailyLifeEvents.I("iMoney")==paid&&DailyLifeEvents.I("iInfantry")==foot+c.Infantry,"no duplicate delivery");}
 foreach(MercenaryContracts.Incident kind in Enum.GetValues(typeof(MercenaryContracts.Incident))){if(kind==MercenaryContracts.Incident.None)continue;VariableSingleton.Instance.RestoreValidated(baseline);int id=4;MercenaryContracts.Sign(id,out _,false);MercenaryContracts.Put(id,"Incident",(int)kind);MercenaryContracts.Put(id,"IncidentDay",MercenaryContracts.Today+1);int enemy=DailyLifeEvents.I("iBazouks"),ships=NavalState.EnemyShips;MercenaryContracts.Advance(VariableSingleton.GetDate().AddDays(1));int after=DailyLifeEvents.I("iBazouks");MercenaryContracts.Advance(VariableSingleton.GetDate().AddDays(1));Check(DailyLifeEvents.I("iBazouks")==after,"no duplicate incident");if(kind==MercenaryContracts.Incident.Traitors)Check(after==enemy+300,"defection land only");if(kind==MercenaryContracts.Incident.Battle)Check(NavalState.EnemyShips>=0&&ships-NavalState.EnemyShips<=3,"enemy ship cap");if(kind==MercenaryContracts.Incident.Disputed){int agents=DailyLifeEvents.I("iSpies");MercenaryContracts.Resolve(id,1);Check(DailyLifeEvents.I("iSpies")==agents-1,"permanent agent");}if(kind==MercenaryContracts.Incident.Greedy){int gold=DailyLifeEvents.I("iMoney");MercenaryContracts.Resolve(id,0);Check(DailyLifeEvents.I("iMoney")==gold-MercenaryContracts.Get(id,"Price")/5,"20 percent surcharge");}}
 VariableSingleton.Instance.RestoreValidated(baseline);
 foreach(var kind in new[]{MercenaryContracts.Incident.Greedy,MercenaryContracts.Incident.Disputed})foreach(int choice in new[]{0,1,2}){VariableSingleton.Instance.RestoreValidated(baseline);MercenaryContracts.Sign(4,out _,false);MercenaryContracts.Put(4,"Incident",(int)kind);MercenaryContracts.Put(4,"IncidentDay",MercenaryContracts.Today+1);MercenaryContracts.Advance(VariableSingleton.GetDate().AddDays(1));MercenaryContracts.Resolve(4,choice);Check(MercenaryContracts.State(4)==(choice==2?MercenaryContracts.Status.Lost:MercenaryContracts.Status.Travelling),"incident choice resolves");}
 VariableSingleton.Instance.RestoreValidated(baseline);MercenaryContracts.Sign(4,out _,false);MercenaryContracts.Put(4,"State",(int)MercenaryContracts.Status.Payment);VariableSingleton.SetInt("iMoney",0);int enemies=DailyLifeEvents.I("iBazouks");MercenaryContracts.Resolve(4,0);Check(MercenaryContracts.State(4)==MercenaryContracts.Status.Payment,"unpaid cannot deliver");MercenaryContracts.Resolve(4,2);MercenaryContracts.Resolve(4,2);Check(DailyLifeEvents.I("iBazouks")==enemies+300,"unpaid defection once");
 VariableSingleton.Instance.RestoreValidated(baseline);
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.4f);MercenaryUI.Show();yield return null;Canvas.ForceUpdateCanvases();var root=GameObject.Find("Mercenary brokers");foreach(var t in root.GetComponentsInChildren<TMP_Text>())Check(!t.isTextOverflowing,"UI text fit "+t.text);foreach(var image in root.GetComponentsInChildren<RawImage>())Check(image.texture!=null,"UI art loaded");ScreenCapture.CaptureScreenshot(Path.Combine(folder,"brokers-"+size.x+".png"));yield return new WaitForSecondsRealtime(.3f);MercenaryUI.Close();}
 }
}
#endif
